package com.akun.xinkun.building;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.block.state.BlockState;

/**
 * A complete, pre-authored structure blueprint. The data comes from a bundled
 * vanilla-format structure file that was exported from a community schematic,
 * so every block, stair, door and interior detail is exactly the original
 * design instead of being generated by code.
 *
 * Coordinates are local: y = 0 is the lowest layer of the blueprint.
 */
public final class BuildBlueprint {
    private final int width;
    private final int depth;
    private int height;
    private final Map<BlockPos, BlockState> blocks = new LinkedHashMap<>();
    private BlockPos doorPos;
    private BlockPos workSpot;
    /** How many bottom layers (environmental water, trees, debris) were trimmed. */
    private int trimmedLayers;

    public BuildBlueprint(int width, int depth, int height) {
        this.width = width;
        this.depth = depth;
        this.height = height;
    }

    public int width() {
        return this.width;
    }

    public int depth() {
        return this.depth;
    }

    public int height() {
        return this.height;
    }

    public Map<BlockPos, BlockState> blocks() {
        return this.blocks;
    }

    public BlockPos doorPos() {
        return this.doorPos;
    }

    public BlockPos workSpot() {
        return this.workSpot;
    }

    /**
     * Number of bottom layers removed while seating the blueprint. Community
     * exports often include the surrounding lake, seabed rubble and trees below
     * the real ground floor; those layers are environmental, not architecture,
     * and are trimmed so the lowest authored layer (the base) is exactly y = 0.
     */
    public int trimmedLayers() {
        return this.trimmedLayers;
    }

    /**
     * Drops every layer below {@code layers} and moves the rest down, so the
     * first kept layer becomes local y = 0. The base of every blueprint is then
     * seated exactly on the build point.
     */
    public void rebase(int layers) {
        if (layers <= 0) {
            this.trimmedLayers = 0;
            return;
        }
        Map<BlockPos, BlockState> rebased = new LinkedHashMap<>();
        for (Map.Entry<BlockPos, BlockState> entry : this.blocks.entrySet()) {
            BlockPos pos = entry.getKey();
            if (pos.getY() < layers) {
                continue;
            }
            rebased.put(pos.offset(0, -layers, 0), entry.getValue());
        }
        this.blocks.clear();
        this.blocks.putAll(rebased);
        if (this.doorPos != null) {
            this.doorPos = this.doorPos.offset(0, -layers, 0);
        }
        if (this.workSpot != null) {
            this.workSpot = this.workSpot.offset(0, -layers, 0);
        }
        this.height = Math.max(1, this.height - layers);
        this.trimmedLayers = layers;
    }

    public void set(int x, int y, int z, BlockState state) {
        this.blocks.put(new BlockPos(x, y, z), state);
    }

    public BlockState get(int x, int y, int z) {
        return this.blocks.get(new BlockPos(x, y, z));
    }

    public void fill(int x1, int y1, int z1, int x2, int y2, int z2, BlockState state) {
        for (int y = Math.min(y1, y2); y <= Math.max(y1, y2); y++) {
            for (int x = Math.min(x1, x2); x <= Math.max(x1, x2); x++) {
                for (int z = Math.min(z1, z2); z <= Math.max(z1, z2); z++) {
                    this.set(x, y, z, state);
                }
            }
        }
    }

    public void setDoorPos(BlockPos doorPos) {
        this.doorPos = doorPos;
    }

    public void setWorkSpot(int x, int y, int z) {
        this.workSpot = new BlockPos(x, y, z);
    }

    public List<Map.Entry<BlockPos, BlockState>> sorted() {
        List<Map.Entry<BlockPos, BlockState>> list = new ArrayList<>(this.blocks.entrySet());
        list.sort((a, b) -> {
            int byY = Integer.compare(a.getKey().getY(), b.getKey().getY());
            if (byY != 0) {
                return byY;
            }
            int byX = Integer.compare(a.getKey().getX(), b.getKey().getX());
            return byX != 0 ? byX : Integer.compare(a.getKey().getZ(), b.getKey().getZ());
        });
        return list;
    }
}
